using System;
using Betta.Interfaces;
using Rhino.Geometry;

namespace BenchPlugin.Facade
{
    /// <summary>One four-sided piece cut from a surface; travels on its own wire.</summary>
    public class Panel : IBettaValue
    {
        public Panel(Point3d c0, Point3d c1, Point3d c2, Point3d c3, int index)
        {
            Corners = new[] { c0, c1, c2, c3 };
            Index = index;
        }

        public Point3d[] Corners { get; }
        public int Index { get; }

        public Curve Outline
        {
            get
            {
                var c = Corners;
                return new PolylineCurve(new[] { c[0], c[1], c[2], c[3], c[0] });
            }
        }

        public double Area =>
            0.5 * Vector3d.CrossProduct(Corners[2] - Corners[0], Corners[3] - Corners[1]).Length;

        public Point3d Center =>
            new Point3d(
                (Corners[0].X + Corners[1].X + Corners[2].X + Corners[3].X) / 4,
                (Corners[0].Y + Corners[1].Y + Corners[2].Y + Corners[3].Y) / 4,
                (Corners[0].Z + Corners[1].Z + Corners[2].Z + Corners[3].Z) / 4);

        /// <summary>Distance from the fourth corner to the plane through the other three.</summary>
        public double Deviation
        {
            get
            {
                var n = Vector3d.CrossProduct(Corners[1] - Corners[0], Corners[2] - Corners[0]);
                double len = n.Length;
                if (len < 1e-12) return 0;
                return Math.Abs(n * (Corners[3] - Corners[0])) / len;
            }
        }

        public double Edge(int i) => Corners[i].DistanceTo(Corners[(i + 1) % 4]);

        /// <summary>Rectangle used for nesting and cut lists.</summary>
        public double Width => (Edge(0) + Edge(2)) / 2;
        public double Height => (Edge(1) + Edge(3)) / 2;

        public double[] SortedEdges()
        {
            var e = new[] { Edge(0), Edge(1), Edge(2), Edge(3) };
            Array.Sort(e);
            return e;
        }

        public double[] SortedDiagonals()
        {
            var d = new[] { Corners[0].DistanceTo(Corners[2]), Corners[1].DistanceTo(Corners[3]) };
            Array.Sort(d);
            return d;
        }
    }
}
