            IProgress<double> progress,
            CancellationToken cancellationToken);

        [GrasshopperMethod("Cut List", "CSV cut list of panel sizes, optionally written to a file")]
        (string CSV, bool Written) CutList(
            [GrasshopperParameter("Panels")] List<Panel> panels,
            [GrasshopperParameter("Path", DefaultValue = "")] string path,
            [GrasshopperParameter("Write", DefaultValue = false)] bool write);
    }

    public class FabricationCollection : IFabricationCollection
    {
        public (List<int> Group, int GroupCount, List<Panel> Representatives) GroupIdenticalPanels(
            List<Panel> panels, double tolerance)
        {
            var groups = new List<int>();
            var reps = new List<Panel>();
            var repEdges = new List<double[]>();
            var repDiags = new List<double[]>();
            foreach (var p in panels ?? new List<Panel>())
            {
                var e = p.SortedEdges();
                var d = p.SortedDiagonals();
                int g = -1;
                for (int k = 0; k < reps.Count && g < 0; k++)
                    if (Close(e, repEdges[k], tolerance) && Close(d, repDiags[k], tolerance)) g = k;
                if (g < 0)
                {
                    g = reps.Count;
                    reps.Add(p);
                    repEdges.Add(e);
                    repDiags.Add(d);
                }
                groups.Add(g);
            }
            return (groups, reps.Count, reps);
        }

        static bool Close(double[] a, double[] b, double tolerance)
        {
            for (int i = 0; i < a.Length; i++)
                if (Math.Abs(a[i] - b[i]) > tolerance) return false;
            return true;
        }

        public Task<(List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization)> NestOnSheets(
            List<Panel> panels, double sheetWidth, double sheetHeight, double spacing,
            IBettaReport report, IProgress<double> progress, CancellationToken cancellationToken)
        {
            var parts = (panels ?? new List<Panel>()).Select(p => (w: p.Width, h: p.Height)).ToList();
            return Task.Run(() =>
            {
                var result = Nest(parts, sheetWidth, sheetHeight, spacing, progress, cancellationToken, out int unplaced);
                if (unplaced > 0) report.Warning($"{unplaced} panels fit on no sheet.");
                return result;
            }, cancellationToken);
        }

        static (List<Curve> Outlines, List<int> Sheet, int SheetCount, double Utilization) Nest(
            List<(double w, double h)> parts, double W, double H, double s,
            IProgress<double> progress, CancellationToken ct, out int unplaced)
        {
            var outlines = new List<Curve>();
            var sheets = new List<int>();
            unplaced = 0;
            double placedArea = 0;
            int sheetCount = 0;
            double x = s, y = s, shelfH = 0;

            var order = Enumerable.Range(0, parts.Count).OrderByDescending(i => parts[i].h).ToList();
            for (int n = 0; n < order.Count; n++)
            {
                ct.ThrowIfCancellationRequested();
                var (w, h) = parts[order[n]];

                bool placed = false;
                double pw = w, ph = h;
                if (sheetCount > 0)
                {
                    if (shelfH > 0 && TryFit(w, h, x, y, W, H, s, shelfH, out pw, out ph))
                        placed = true;
                    else if (TryFit(w, h, s, y + shelfH + s, W, H, s, double.MaxValue, out pw, out ph))
                    {
                        y += shelfH + s; x = s; shelfH = 0; placed = true;
                    }
                }
                if (!placed && TryFit(w, h, s, s, W, H, s, double.MaxValue, out pw, out ph))
                {
                    sheetCount++; x = s; y = s; shelfH = 0; placed = true;
                }

                if (placed)
                {
                    double ox = (sheetCount - 1) * (W + 100);
                    outlines.Add(new PolylineCurve(new[]
                    {
                        new Point3d(ox + x, y, 0), new Point3d(ox + x + pw, y, 0),
                        new Point3d(ox + x + pw, y + ph, 0), new Point3d(ox + x, y + ph, 0),
                        new Point3d(ox + x, y, 0),
                    }));
                    sheets.Add(sheetCount - 1);
                    placedArea += w * h;
                    if (shelfH == 0) shelfH = ph;
                    x += pw + s;
                }
                else unplaced++;

                progress?.Report((n + 1.0) / order.Count);
            }

            double util = sheetCount == 0 ? 0 : placedArea / (sheetCount * W * H);
            return (outlines, sheets, sheetCount, util);
        }

        /// <summary>Fits unturned first, then turned 90 degrees.</summary>
        static bool TryFit(double w, double h, double x, double y, double W, double H, double s,
            double shelfH, out double pw, out double ph)
        {
            pw = w; ph = h;
            if (x + w + s <= W && y + h + s <= H && h <= shelfH) return true;
            pw = h; ph = w;
            if (x + h + s <= W && y + w + s <= H && w <= shelfH) return true;
            return false;
        }

        public (string CSV, bool Written) CutList(List<Panel> panels, string path, bool write)
        {
            if (write && string.IsNullOrWhiteSpace(path)) throw new ArgumentException("Path is empty.");
            var inv = CultureInfo.InvariantCulture;
            var sb = new StringBuilder("Index,Width,Height,Area,Deviation\n");
            foreach (var p in panels ?? new List<Panel>())
                sb.Append(string.Join(",", p.Index.ToString(inv), p.Width.ToString(inv), p.Height.ToString(inv),
                    p.Area.ToString(inv), p.Deviation.ToString(inv))).Append('\n');
            string csv = sb.ToString();
            if (!write) return (csv, false);
            File.WriteAllText(path, csv);
            return (csv, true);
        }
    }
}
